#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.HeldItems;
using MVZ2Logic;
using MVZ2Logic.HeldItems;
using MVZ2Logic.Level;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace MVZ2.GameContent.HeldItems
{
    [HeldItemBehaviourDefinition(VanillaHeldItemBehaviourNames.relocateSkywardFamiliar)]
    public class RelocateSkywardFamiliarBehaviour : HeldItemBehaviourDefinition
    {
        public RelocateSkywardFamiliarBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override HeldTargetFlag GetHeldTargetMask(LevelEngine level)
        {
            return HeldTargetFlag.Plant;
        }
        public override bool IsValidFor(IHeldItemTarget target, IHeldItemData data, PointerInteractionData pointer)
        {
            if (target is not HeldItemTargetEntity entityTarget)
                return false;

            var entity = entityTarget.Target;
            switch (entity.Type)
            {
                case EntityTypes.PLANT:
                    return entity.IsEntityOf(VanillaContraptionID.skywardFamiliar);
            }
            return false;
        }
        public override HeldHighlight GetHighlight(IHeldItemTarget target, IHeldItemData data, PointerInteractionData pointer)
        {
            if (target is not HeldItemTargetEntity entityTarget)
                return HeldHighlight.None;

            var entity = entityTarget.Target;
            switch (entity.Type)
            {
                case EntityTypes.PLANT:
                    return HeldHighlight.Entity(entity);
            }
            return HeldHighlight.None;
        }
        public override void OnPointerEvent(IHeldItemTarget target, IHeldItemData data, PointerInteractionData pointerParams)
        {
            if (target is not HeldItemTargetEntity entityTarget)
                return;
            if (pointerParams.IsInvalidClickButton())
                return;
            var interaction = pointerParams.interaction;
            var entity = entityTarget.Target;
            switch (entity.Type)
            {
                case EntityTypes.PLANT:
                    if (interaction == PointerInteraction.Down)
                    {
                        var builder = new HeldItemBuilder(VanillaHeldTypes.skywardFamiliar, 100);
                        builder.SetEntityID(entity.ID);
                        entity.Level.SetHeldItem(builder);
                    }
                    break;
            }
        }
    }
}
